{"implementation":"def solve(case):
    threshold = case.get('threshold')
    calls = case.get('calls')
    if threshold is None or calls is None:
        raise ValueError('Missing threshold or calls')
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        pred_tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if None in (call_id, loss_without, loss_with, pred_tokens, parseable):
            raise ValueError(f'Missing field in call {call}')
        if pred_tokens <= 0:
            raise ValueError('prediction_tokens must be positive')
        gain = loss_without - loss_with
        normalized = gain / pred_tokens
        is_accepted = parseable and normalized >= threshold
        if is_accepted:
            accepted.append(call_id)
        diagnostics.append({
            'accepted': is_accepted,
            'call_id': call_id,
            'normalized_gain': normalized
        })
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }"}
